diesel::table! {
    public.local_sessions (id) {
        id -> Uuid,
        user_id -> Uuid,
        token_hash -> Text,
        created_at -> Timestamptz,
        expires_at -> Timestamptz,
        last_used_at -> Nullable<Timestamptz>,
        revoked_at -> Nullable<Timestamptz>,
    }
}

diesel::table! {
    public.organization_members (organization_id, user_id) {
        organization_id -> Uuid,
        user_id -> Uuid,
        role -> Text,
        joined_at -> Timestamptz,
    }
}

diesel::table! {
    public.organizations (id) {
        id -> Uuid,
        name -> Text,
        slug -> Text,
        created_at -> Timestamptz,
        updated_at -> Timestamptz,
    }
}

diesel::table! {
    public.system_board_defaults (id) {
        id -> Uuid,
        board_level -> Text,
        #[sql_name = "columns"]
        columns_ -> Text,
        transitions -> Text,
    }
}

diesel::table! {
    public.system_metadata_definition_scopes (metadata_definition_id, entity_type) {
        metadata_definition_id -> Uuid,
        entity_type -> Text,
    }
}

diesel::table! {
    public.system_metadata_definitions (id) {
        id -> Uuid,
        name -> Text,
        slug -> Text,
        field_type -> Text,
        created_at -> Timestamptz,
        updated_at -> Timestamptz,
    }
}

diesel::table! {
    public.system_metadata_enum_options (id) {
        id -> Uuid,
        metadata_definition_id -> Uuid,
        value -> Text,
        position -> Int4,
    }
}

diesel::table! {
    public.system_template_metadata (id) {
        id -> Uuid,
        template_id -> Uuid,
        metadata_definition_id -> Uuid,
        default_value -> Nullable<Text>,
        required -> Bool,
    }
}

diesel::table! {
    public.system_templates (id) {
        id -> Uuid,
        name -> Text,
        slug -> Text,
        content -> Text,
        created_at -> Timestamptz,
        updated_at -> Timestamptz,
    }
}

diesel::table! {
    public.users (id) {
        id -> Uuid,
        external_id -> Text,
        email -> Text,
        display_name -> Text,
        created_at -> Timestamptz,
        updated_at -> Timestamptz,
        kind -> Text,
        user_name -> Text,
        password_hash -> Nullable<Text>,
    }
}

